steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query {
      issues(filter: {
        title: {contains: \"checkout\"},
        assignee: {name: {contains: \"Priya Nair\"}}
      }) {
        nodes {
          id
          identifier
          title
          priority
          assignee { name }
          team { key name }
          milestone { name }
        }
      }
    }"
  }'
